import Link from 'next/link';

export default function Forbidden() {
  return (
    <main style={{ padding: '2rem', textAlign: 'center' }}>
      <h1>403 - Forbidden</h1>
      <p>You do not have permission to access this page.</p>
      <Link href="/">Return Home</Link>
    </main>
  );
}

